package in.tucor.api.auth; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="refresh_tokens") public class RefreshToken {@Id public UUID id; @Column(name="user_id",nullable=false) public UUID userId; @Column(name="token_hash",nullable=false,unique=true) public String tokenHash; @Column(name="expires_at",nullable=false) public Instant expiresAt; @Column(name="revoked_at") public Instant revokedAt; @Column(name="created_at",nullable=false) public Instant createdAt; @PrePersist void create(){if(id==null)id=UUID.randomUUID();if(createdAt==null)createdAt=Instant.now();}}